/**
 * Header DXP Component Service - Server-Side Renderer
 *
 * Uses the hydration pattern: server renders a minimal container with data
 * attributes; the client-side hydration bundle (dist/hydrate.min.js) mounts
 * the React Header from window.NTGDesignSystem on DOMContentLoaded.
 */

/**
 * Escape a string for safe insertion into an HTML attribute value.
 * @param {unknown} value
 * @returns {string}
 */
function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

/**
 * Generate a short unique id for an instance of the component.
 * @returns {string}
 */
function generateInstanceId() {
  return `hdr-${Math.random().toString(36).slice(2, 11)}`;
}

export default {
  async render(input) {
    const {
      variant = "nt-gov-au",
      agencyName,
      agencyHref = "/",
      logoAlt = "NT.GOV.AU",
      navItems = [],
      showSearch = true,
      searchVariant = "expanded",
      searchPlaceholder = "Search",
      searchAction = "/search",
    } = input || {};

    const props = {
      variant,
      agencyHref,
      logoAlt,
      navItems,
      showSearch,
      searchVariant,
      searchPlaceholder,
      searchAction,
    };
    if (agencyName) {
      props.agencyName = agencyName;
    }

    const instanceId = generateInstanceId();
    const hydrationProps = escapeHtml(JSON.stringify(props));

    // Minimal noscript fallback so the page is still usable without JS.
    const noscriptFallback = `<noscript><div class="header header--noscript"><a href="${escapeHtml(
      variant === "nt-gov-au" ? "https://nt.gov.au" : agencyHref,
    )}" class="header__logo-link">${escapeHtml(
      agencyName || logoAlt || "NT Government",
    )}</a></div></noscript>`;

    return `<div class="ntg-header-hydration" data-hydration-component="header" data-hydration-props="${hydrationProps}" data-instance-id="${instanceId}">${noscriptFallback}</div>`;
  },
};
